48	/// Name this invocation was launched under: `argv[0]`'s basename,
49	/// falling back to the compiled bin name when argv is empty or
50	/// unreadable. Runtime on purpose: beyond the two `[[bin]]`
51	/// targets, a suffixed install copy (`vc-x1-dev-<bookmark>`, the
52	/// concurrent-dev-lines convention) self-reports the name it
53	/// actually runs as, which no compile-time constant can know.
54	fn invoked_name() -> String {
55	    std::env::args_os()
56	        .next()
57	        .as_deref()
58	        .and_then(|p| Path::new(p).file_name())
59	        .map(|n| n.to_string_lossy().into_owned())
60	        .unwrap_or_else(|| env!("CARGO_BIN_NAME").to_string())
61	}
