63	/// Banner string emitted as the first line of every run (stderr,
64	/// or stdout when `-V` asked for it), and shown at the top of
65	/// subcommand `--help` output: `<invoked name> <version>`.
66	fn banner() -> &'static str {
67	    static BANNER: std::sync::OnceLock<String> = std::sync::OnceLock::new();
68	    BANNER.get_or_init(|| format!("{} {}", invoked_name(), env!("CARGO_PKG_VERSION")))
69	}
