79	/// Build the clap command tree with `BANNER` set as `before_help`
80	/// on every subcommand (transitively). Top-level skips `before_help`
81	/// because its own `about` already carries the name+version+tagline.
82	/// Walks via `mut_subcommand` so individual subcommand
83	/// `#[command(long_about = ...)]` blocks don't have to repeat the
84	/// banner text.
85	fn cli_with_banner() -> clap::Command {
86	    fn add_to_subs(mut cmd: clap::Command) -> clap::Command {
87	        let names: Vec<String> = cmd
88	            .get_subcommands()
89	            .map(|c| c.get_name().to_string())
90	            .collect();
91	        for name in names {
92	            cmd = cmd.mut_subcommand(name, add_with_banner);
93	        }
94	        cmd
95	    }
96	    fn add_with_banner(mut cmd: clap::Command) -> clap::Command {
97	        cmd = cmd.before_help(banner());
98	        let names: Vec<String> = cmd
99	            .get_subcommands()
100	            .map(|c| c.get_name().to_string())
101	            .collect();
102	        for name in names {
103	            cmd = cmd.mut_subcommand(name, add_with_banner);
104	        }
105	        cmd
106	    }
107	    add_to_subs(Cli::command())
108	}
