/// The single-name convention's mechanical guard (chores-16,
/// 0.78.3): a suffixed version marks a dev rung, and a dev
/// rung must never carry the stable name, or the per-commit
/// flow's `cargo install` replaces the stable `vc-x1` binary
/// with unpushed code. Compile-time facts only, so it runs
/// identically in every checkout, and it sits in the test
/// gate, which precedes the install gate in both validation
/// tiers. The mild direction (a dev name reaching main with a
/// bare version) stays procedural: enforcing it here would
/// fail branch close-outs that rename at their merge commit.
#[test]
fn dev_rung_never_wears_the_stable_name() {
    let version = env!("CARGO_PKG_VERSION");
    let name = env!("CARGO_PKG_NAME");
    if version.contains('-') {
        assert_ne!(
            name, "vc-x1",
            "suffixed version {version} (a dev rung) under the stable package \
             name: rename [package].name at cycle open, or the validation \
             install will clobber the stable vc-x1 binary"
        );
    }
}

